    const auto work=fs::temp_directory_path()/("OPENFRUIT-aea-decode-"+NewOperationId());fs::create_directory(work);const auto original=work/"original.aea";std::ofstream(original,std::ios::binary).write(vectors[0].data(),vectors[0].size());
    auto stage=JsonValue::ObjectValue(),input=JsonValue::ObjectValue();input.Set("path",JsonValue::String(original.generic_string()));input.Set("sha256",JsonValue::String(Sha256(vectors[0]).value_or("")));input.Set("stream_verified",JsonValue::Boolean(true));input.Set("encrypted_input_retained",JsonValue::Boolean(true));input.Set("declared_hash_method",JsonValue::String("sha2-256"));input.Set("declared_digest",JsonValue::String(std::string(64,'0')));auto outputs=JsonValue::ArrayValue();outputs.ArrayItems().push_back(input);stage.Set("outputs",outputs);const auto report=work/"stage.json";std::ofstream(report)<<stage.Serialize();
